import pandas as pd

timesheet = pd.read_csv('/app/dataset/timesheet.csv')

# Simple date parser
def parse_date(d_str):
    if d_str == '2025-06-31':
        return pd.to_datetime('2025-06-30')
    if d_str == '2025-04-31':
        return pd.to_datetime('2025-04-30')
    return pd.to_datetime(d_str, format='%Y-%m-%d')

timesheet['parsed_date'] = timesheet['date'].apply(parse_date)

# Let's count records on each date and see if we can check our period ranges
# First Tuesday of March 2025: March 4
# First Tuesday of April 2025: April 1
# First Tuesday of May 2025: May 6
# First Tuesday of June 2025: June 3
# First Tuesday of July 2025: July 1

# Let's map each date to its period
def get_period(d):
    if pd.to_datetime('2025-03-04') <= d < pd.to_datetime('2025-04-01'):
        return 'March (03-04 to 03-31)'
    elif pd.to_datetime('2025-04-01') <= d < pd.to_datetime('2025-05-06'):
        return 'April (04-01 to 05-05)'
    elif pd.to_datetime('2025-05-06') <= d < pd.to_datetime('2025-06-03'):
        return 'May (05-06 to 06-02)'
    elif pd.to_datetime('2025-06-03') <= d <= pd.to_datetime('2025-06-30'):
        return 'June (06-03 to 06-30)'
    else:
        return f'Other: {d.strftime("%Y-%m-%d")}'

timesheet['period'] = timesheet['parsed_date'].apply(get_period)
print(timesheet['period'].value_counts().sort_index())

